using namespace std;

const int dx[4] = {1, -1, 0, 0};
const int dy[4] = {0, 0, 1, -1};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int H, W;
    while (cin >> H >> W, H || W) {
        vector<string> grid(H);
        for (int i = 0; i < H; i++) cin >> grid[i];

        int black = 0, white = 0;

        for (int i = 0; i < H; i++) {
            for (int j = 0; j < W; j++) {
                if (grid[i][j] != '.') continue;

                // BFS from this empty cell to find its enclosing color
                queue<pair<int,int>> q;
                q.push({i, j});
                grid[i][j] = 'X'; // mark visited
                bool touchesB = false, touchesW = false;
                int area = 0;

                while (!q.empty()) {
                    auto [x, y] = q.front(); q.pop();
                    area++;

                    for (int d = 0; d < 4; d++) {
                        int nx = x + dx[d];
                        int ny = y + dy[d];
                        if (nx < 0 || nx >= H || ny < 0 || ny >= W) {
                            // touches border -> not fully enclosed
                            touchesB = true;
                            touchesW = true;
                            continue;
                        }
                        if (grid[nx][ny] == 'B') touchesB = true;
                        else if (grid[nx][ny] == 'W') touchesW = true;
                        else if (grid[nx][ny] == '.') {
                            grid[nx][ny] = 'X';
                            q.push({nx, ny});
                        }
                    }
                }

                // If only one color touches this region
                if (touchesB && !touchesW) black += area;
                else if (!touchesB && touchesW) white += area;
            }
        }

        cout << black << " " << white << "\n";
    }
    return 0;
}

