        if (W == 0 && H == 0) break;

        vector<string> g(H);
        for (int i = 0; i < H; ++i) cin >> g[i];

        vector<vector<int>> vis(H, vector<int>(W, 0));
        int blackArea = 0, whiteArea = 0;

        const int dx[4] = {1, -1, 0, 0};
        const int dy[4] = {0, 0, 1, -1};

        for (int sy = 0; sy < H; ++sy) {
            for (int sx = 0; sx < W; ++sx) {
                if (g[sy][sx] != '.' || vis[sy][sx]) continue;

                queue<pair<int,int>> q;
                vector<pair<int,int>> comp;
                q.push({sy, sx});
                vis[sy][sx] = 1;

                bool touchesBoundary = false;
                bool adjB = false, adjW = false;

                while (!q.empty()) {
                    auto [y, x] = q.front();
                    q.pop();
                    comp.push_back({y, x});

                    if (y == 0 || y == H - 1 || x == 0 || x == W - 1)
                        touchesBoundary = true;

                    for (int dir = 0; dir < 4; ++dir) {
                        int ny = y + dy[dir], nx = x + dx[dir];
                        if (ny < 0 || ny >= H || nx < 0 || nx >= W) continue;

                        if (g[ny][nx] == '.') {
                            if (!vis[ny][nx]) {
                                vis[ny][nx] = 1;
                                q.push({ny, nx});
                            }
                        } else if (g[ny][nx] == 'B') {
                            adjB = true;
                        } else if (g[ny][nx] == 'W') {
                            adjW = true;
                        }
                    }
                }

                if (!touchesBoundary) {
                    if (adjB && !adjW) blackArea += (int)comp.size();
                    else if (adjW && !adjB) whiteArea += (int)comp.size();
                }
            }
        }

        cout << blackArea << ' ' << whiteArea << '\n';
    }

    return 0;
}

