from collections import deque

def solve():
    data = sys.stdin.read().splitlines()
    out = []
    i = 0

    while i < len(data):
        line = data[i].strip()
        i += 1
        if not line:
            continue
        h, w = map(int, line.split())
        if h == 0 and w == 0:
            break

        grid = []
        for _ in range(h):
            grid.append(list(data[i].rstrip('\n')))
            i += 1

        # Flood fill empty cells from the outside.
        # Cells not reachable from outside are enclosed regions.
        ext_h, ext_w = h + 2, w + 2
        ext = [['.'] * ext_w for _ in range(ext_h)]
        for r in range(h):
            for c in range(w):
                ext[r + 1][c + 1] = grid[r][c]

        vis = [[False] * ext_w for _ in range(ext_h)]
        q = deque([(0, 0)])
        vis[0][0] = True
        dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]

        while q:
            x, y = q.popleft()
            for dx, dy in dirs:
                nx, ny = x + dx, y + dy
                if 0 <= nx < ext_h and 0 <= ny < ext_w and not vis[nx][ny] and ext[nx][ny] == '.':
                    vis[nx][ny] = True
                    q.append((nx, ny))

        black_area = 0
        white_area = 0
        seen = [[False] * ext_w for _ in range(ext_h)]

        # For each enclosed empty region, determine which color surrounds it.
        for r in range(1, h + 1):
            for c in range(1, w + 1):
                if ext[r][c] == '.' and not vis[r][c] and not seen[r][c]:
                    q = deque([(r, c)])
                    seen[r][c] = True
                    region_size = 0
                    border_colors = set()

                    while q:
                        x, y = q.popleft()
                        region_size += 1
                        for dx, dy in dirs:
                            nx, ny = x + dx, y + dy
                            ch = ext[nx][ny]
                            if ch == '.':
                                if not vis[nx][ny] and not seen[nx][ny]:
                                    seen[nx][ny] = True
                                    q.append((nx, ny))
                            elif ch == 'B' or ch == 'W':
                                border_colors.add(ch)

                    # By problem statement / test design, an enclosed region
                    # belongs to exactly one color.
                    if border_colors == {'B'}:
                        black_area += region_size
                    elif border_colors == {'W'}:
                        white_area += region_size

        out.append(f"{black_area} {white_area}")

    sys.stdout.write("\n".join(out))

