#include <stdio.h>
#include <string.h>
#include <stdbool.h>

#define MAX_H 50
#define MAX_W 50

int h, w;
char grid[MAX_H][MAX_W + 1];
bool visited[MAX_H][MAX_W];

// Directions: up, down, left, right
int dx[] = {-1, 1, 0, 0};
int dy[] = {0, 0, -1, 1};

void flood_fill(int x, int y, char color, int* area) {
    if (x < 0 || x >= h || y < 0 || y >= w) return;
    if (visited[x][y]) return;
    if (grid[x][y] != '.') return;

    visited[x][y] = true;
    (*area)++;

    for (int d = 0; d < 4; d++) {
        int nx = x + dx[d];
        int ny = y + dy[d];
        flood_fill(nx, ny, color, area);
    }
}

bool can_reach_boundary(int x, int y, char color) {
    // Check if from this cell we can reach a cell of opposite color or boundary
    // Actually we check if there is a path to a cell that is not enclosed

    // Simple approach: BFS/DFS but we check if we can reach an edge or a stake of opposite color
    // For simplicity, we do DFS and mark
    if (x < 0 || x >= h || y < 0 || y >= w) return true;
    if (grid[x][y] != '.') return false;
    if (visited[x][y]) return false;

    visited[x][y] = true;

    // Check if adjacent to boundary
    if (x == 0 || x == h-1 || y == 0 || y == w-1) return true;

    for (int d = 0; d < 4; d++) {
        int nx = x + dx[d];
        int ny = y + dy[d];
        if (nx >= 0 && nx < h && ny >= 0 && ny < w) {
            if (grid[nx][ny] == '.' && !visited[nx][ny]) {
                if (can_reach_boundary(nx, ny, color)) return true;
            }
        }
    }
    return false;
}

bool is_surrounded_by(int x, int y, char color) {
    // Check if cell (x,y) is surrounded by 'color' stakes
    // That means from this cell, any direction you go, you hit 'color' before the other color or boundary

    // We do BFS/DFS from this cell, and if we ever reach a cell of opposite color or boundary, it's not surrounded
    // We only go through '.' cells

    // Reset visited for this check
    bool temp_visited[MAX_H][MAX_W] = {false};

    // Use stack for DFS
    int stack_x[MAX_H * MAX_W];
    int stack_y[MAX_H * MAX_W];
    int top = 0;

    stack_x[top] = x;
    stack_y[top] = y;
    top++;
    temp_visited[x][y] = true;

    while (top > 0) {
        top--;
        int cx = stack_x[top];
        int cy = stack_y[top];

        // Check if we are at boundary -> not surrounded
        if (cx == 0 || cx == h-1 || cy == 0 || cy == w-1) {
            return false;
        }

        for (int d = 0; d < 4; d++) {
            int nx = cx + dx[d];
            int ny = cy + dy[d];

            if (nx < 0 || nx >= h || ny < 0 || ny >= w) continue;

            if (grid[nx][ny] == '.') {
                if (!temp_visited[nx][ny]) {
                    temp_visited[nx][ny] = true;
                    stack_x[top] = nx;
                    stack_y[top] = ny;
                    top++;
                }
            } else if (grid[nx][ny] != color) {
                // Found opposite color -> not surrounded by this color
                return false;
            }
            // If grid[nx][ny] == color, it's fine, continue
        }
    }

    // If we never found opposite color or boundary, it's surrounded by 'color'
    return true;
}

int main() {
    while (1) {
        scanf("%d %d", &h, &w);
        if (h == 0 && w == 0) break;

        for (int i = 0; i < h; i++) {
            scanf("%s", grid[i]);
        }

        // Mark all '.' cells that are reachable from boundary (i.e., not enclosed)
        // First, find all '.' cells that are not enclosed by any stakes
        bool enclosed[MAX_H][MAX_W] = {false};

        // For each '.' cell, determine if it's surrounded by black or white
        int black_area = 0, white_area = 0;

        // We'll compute for each '.' cell which color it belongs to
        // Actually we need to compute total area of cells surrounded by each color

        // Approach: For each '.' cell, check if it is surrounded by black or white
        // But we need to group connected components of '.' that are surrounded by same color

        // Better: For each '.' cell, if it's not visited, do BFS to find its region
        // and determine which color(s) surround it.

        memset(visited, 0, sizeof(visited));

        for (int i = 0; i < h; i++) {
            for (int j = 0; j < w; j++) {
                if (grid[i][j] == '.' && !visited[i][j]) {
                    // Start BFS for this region
                    int region_cells = 0;
                    bool touches_black = false, touches_white = false;
                    bool touches_boundary = false;

                    // BFS
                    int queue_x[MAX_H * MAX_W];
                    int queue_y[MAX_H * MAX_W];
                    int front = 0, rear = 0;

                    queue_x[rear] = i;
                    queue_y[rear] = j;
                    rear++;
                    visited[i][j] = true;
                    region_cells++;

                    while (front < rear) {
                        int cx = queue_x[front];
                        int cy = queue_y[front];
                        front++;

                        // Check boundaries
                        if (cx == 0 || cx == h-1 || cy == 0 || cy == w-1) {
                            touches_boundary = true;
                        }

                        for (int d = 0; d < 4; d++) {
                            int nx = cx + dx[d];
                            int ny = cy + dy[d];

                            if (nx < 0 || nx >= h || ny < 0 || ny >= w) {
                                touches_boundary = true;
                                continue;
                            }

                            if (grid[nx][ny] == 'B') {
                                touches_black = true;
                            } else if (grid[nx][ny] == 'W') {
                                touches_white = true;
                            } else if (grid[nx][ny] == '.' && !visited[nx][ny]) {
                                visited[nx][ny] = true;
                                queue_x[rear] = nx;
                                queue_y[rear] = ny;
                                rear++;
                                region_cells++;
                            }
                        }
                    }

                    // Determine ownership
                    if (touches_boundary) {
                        // Not enclosed by either
                        continue;
                    }
                    if (touches_black && !touches_white) {
                        black_area += region_cells;
                    } else if (touches_white && !touches_black) {
                        white_area += region_cells;
                    }
                    // If both or none, it's disputed or not enclosed -> ignore
                }
            }
        }

        printf("%d %d\n", black_area, white_area);
    }
    return 0;
}

