typedef struct {
    int y, x;
} Node;

char g[MAXH][MAXW];
int vis[MAXH][MAXW];
Node q[MAXQ];

int main(void) {
    int H, W;
    while (scanf("%d %d", &H, &W) == 2) {
        if (H == 0 && W == 0) break;

        for (int i = 0; i < H; i++) {
            scanf("%s", g[i]);
        }

        memset(vis, 0, sizeof(vis));

        int black = 0, white = 0;
        int dy[4] = {-1, 1, 0, 0};
        int dx[4] = {0, 0, -1, 1};

        for (int sy = 0; sy < H; sy++) {
            for (int sx = 0; sx < W; sx++) {
                if (g[sy][sx] != '.' || vis[sy][sx]) continue;

                int head = 0, tail = 0;
                q[tail++] = (Node){sy, sx};
                vis[sy][sx] = 1;

                int cnt = 0;
                int touchB = 0, touchW = 0;

                while (head < tail) {
                    Node cur = q[head++];
                    cnt++;

                    for (int dir = 0; dir < 4; dir++) {
                        int ny = cur.y + dy[dir];
                        int nx = cur.x + dx[dir];

                        if (ny < 0 || ny >= H || nx < 0 || nx >= W) continue;

                        if (g[ny][nx] == '.') {
                            if (!vis[ny][nx]) {
                                vis[ny][nx] = 1;
                                q[tail++] = (Node){ny, nx};
                            }
                        } else if (g[ny][nx] == 'B') {
                            touchB = 1;
                        } else if (g[ny][nx] == 'W') {
                            touchW = 1;
                        }
                    }
                }

                if (touchB && !touchW) black += cnt;
                else if (touchW && !touchB) white += cnt;
            }
        }

        printf("%d %d\n", black, white);
    }

    return 0;
}

