            int[] dx = {0,0,1,-1}, dy = {1,-1,0,0};
            while (!queue.isEmpty()) {
                int[] cur = queue.poll();
                for (int d = 0; d < 4; d++) {
                    int nx = cur[0]+dx[d], ny = cur[1]+dy[d];
                    if (nx>=0&&nx<H&&ny>=0&&ny<W&&!outside[nx][ny]&&grid[nx][ny]=='.') {
                        outside[nx][ny] = true;
                        queue.add(new int[]{nx,ny});
                    }
                }
            }

            int blackArea = 0, whiteArea = 0;
            boolean[][] visited = new boolean[H][W];
            for (int i = 0; i < H; i++) for (int j = 0; j < W; j++) {
                if (grid[i][j]=='.' && !outside[i][j] && !visited[i][j]) {
                    List<int[]> comp = new ArrayList<>();
                    Queue<int[]> q2 = new LinkedList<>();
                    q2.add(new int[]{i,j}); visited[i][j]=true;
                    boolean hasB=false, hasW=false;
                    while (!q2.isEmpty()) {
                        int[] c = q2.poll(); comp.add(c);
                        for (int d=0;d<4;d++) {
                            int nx=c[0]+dx[d],ny=c[1]+dy[d];
                            if (nx<0||nx>=H||ny<0||ny>=W) continue;
                            if (grid[nx][ny]=='B') hasB=true;
                            if (grid[nx][ny]=='W') hasW=true;
                            if (grid[nx][ny]=='.'&&!visited[nx][ny]&&!outside[nx][ny]) {
                                visited[nx][ny]=true; q2.add(new int[]{nx,ny});
                            }
                        }
                    }
                    if (hasB&&!hasW) blackArea+=comp.size();
                    else if (hasW&&!hasB) whiteArea+=comp.size();
                }
            }
            System.out.println(blackArea + " " + whiteArea);
        }
    }
}

