                    // But in our BFS we don't record that. Let's restructure:
                    // We'll first check if component touches border.
                    // Simpler: during BFS, if we encounter a border cell (adjacent to outside)
                    // we can set a flag.
                }
            }
        }

        // Actually we need to redo: we must know if component touches border.
        // Let's do the BFS again properly with border detection.
        // Since we already have visited, we need to re-explore but with fresh visited for this component?
        // Let's just do a separate method that uses a temporary visited for one component.
        // Simpler: we'll call a new function that does not use global visited for component detection.
        // We'll just redo the BFS with a local visited for this component.
        // But we've already marked visited globally. So we need to unmark? That's messy.
        // Better approach: do BFS and detect border at the same time.
        // Let's rewrite exploreComponent properly.
        return exploreComponentProper(startR, startC);
    }

    static int[] exploreComponentProper(int startR, int startC) {
        Queue<int[]> queue = new LinkedList<>();
        queue.add(new int[]{startR, startC});
        visited[startR][startC] = true;

        int area = 0;
        boolean touchesBorder = false;
        boolean hasBlack = false;
        boolean hasWhite = false;

        while (!queue.isEmpty()) {
            int[] cell = queue.poll();
            int r = cell[0], c = cell[1];
            area++;

            for (int d = 0; d < 4; d++) {
                int nr = r + dr[d];
                int nc = c + dc[d];

                if (nr < 0 || nr >= H || nc < 0 || nc >= W) {
                    touchesBorder = true;
                    continue;
                }

                char ch = grid[nr][nc];
                if (ch == 'B') {
                    hasBlack = true;
                } else if (ch == 'W') {
                    hasWhite = true;
                } else if (ch == '.' && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    queue.add(new int[]{nr, nc});
                }
            }
        }

        if (touchesBorder) {
            // Not enclosed by stakes at all
            return new int[]{0, area}; // type 0 means not counted
        }

        if (hasBlack && !hasWhite) {
            return new int[]{1, area};
        } else if (hasWhite && !hasBlack) {
            return new int[]{2, area};
        } else {
            // either both or none
            return new int[]{3, area}; // not counted
        }
    }

