import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    static int H, W;
    static char[][] grid;
    static boolean[][] vis;
    static final int[] dr = {-1, 1, 0, 0};
    static final int[] dc = {0, 0, -1, 1};

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        String first;
        StringBuilder out = new StringBuilder();

        while ((first = fs.next()) != null) {
            H = Integer.parseInt(first);
            W = fs.nextInt();
            if (H == 0 && W == 0) break;

            grid = new char[H][W];
            for (int i = 0; i < H; i++) {
                String s = fs.next();
                grid[i] = s.toCharArray();
            }

            vis = new boolean[H][W];
            int blackArea = 0;
            int whiteArea = 0;

            for (int i = 0; i < H; i++) {
                for (int j = 0; j < W; j++) {
                    if (grid[i][j] == '.' && !vis[i][j]) {
                        int[] res = explore(i, j);
                        int area = res[0];
                        int touchesOutside = res[1];
                        int touchesBlack = res[2];
                        int touchesWhite = res[3];

                        if (touchesOutside == 0) {
                            if (touchesBlack > 0 && touchesWhite == 0) blackArea += area;
                            else if (touchesWhite > 0 && touchesBlack == 0) whiteArea += area;
                        }
                    }
                }
            }

            out.append(blackArea).append(' ').append(whiteArea).append('\n');
        }

        System.out.print(out.toString());
    }

    // returns {area, touchesOutside(0/1), touchesBlack(0/1), touchesWhite(0/1)}
    static int[] explore(int sr, int sc) {
        ArrayDeque<int[]> q = new ArrayDeque<>();
        q.add(new int[]{sr, sc});
        vis[sr][sc] = true;

        int area = 0;
        int outside = 0;
        int black = 0;
        int white = 0;

        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int r = cur[0], c = cur[1];
            area++;

            for (int k = 0; k < 4; k++) {
                int nr = r + dr[k];
                int nc = c + dc[k];

                if (nr < 0 || nr >= H || nc < 0 || nc >= W) {
                    outside = 1;
                    continue;
                }

                char ch = grid[nr][nc];
                if (ch == '.') {
                    if (!vis[nr][nc]) {
                        vis[nr][nc] = true;
                        q.add(new int[]{nr, nc});
                    }
                } else if (ch == 'B') {
                    black = 1;
                } else if (ch == 'W') {
                    white = 1;
                }
            }
        }

        return new int[]{area, outside, black, white};
    }
}
